import React, { useState, useEffect } from 'react';
import { Order } from './types';
import { apiService } from './services/apiService';
import { socketService } from './services/socketService';
import OrderCard from './components/OrderCard';
import OrderStats from './components/OrderStats';
import LoadingSpinner from './components/LoadingSpinner';
import './index.css';

const App: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [connected, setConnected] = useState(false);
  const [newOrderCount, setNewOrderCount] = useState(0);

  useEffect(() => {
    fetchOrders();
    setupWebSocket();

    return () => {
      socketService.disconnect();
    };
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const fetchedOrders = await apiService.getOrders();
      setOrders(fetchedOrders);
      setError(null);
    } catch (err) {
      setError('Failed to fetch orders');
      console.error('Error fetching orders:', err);
    } finally {
      setLoading(false);
    }
  };

  const setupWebSocket = () => {
    socketService.connect();

    socketService.on('new-order', (event) => {
      setOrders(prev => [event.data, ...prev]);
      setNewOrderCount(prev => prev + 1);

      // Play notification sound (optional)
      const audio = new Audio('data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoGAACBhYqFbF1fdJivrJBhNjVgodDbq2EcBj+a2/LDciUFLIHO8tiJNwgZaLvt559NEAxQp+PwtmMcBjiR1/LMeSwFJHfH8N2QQAoUXrTp66hVFApGn+DyvmwhBTGH0fPTgjMGHm7A7+OZURE');
      audio.play().catch(() => {});
    });

    socketService.on('order-status-update', (event) => {
      setOrders(prev => 
        prev.map(order => 
          order._id === event.orderId ? event.data : order
        )
      );
    });

    socketService.on('order-deleted', (event) => {
      setOrders(prev => prev.filter(order => order._id !== event.orderId));
    });

    setConnected(socketService.isConnected());
  };

  const handleOrderUpdate = (updatedOrder: Order) => {
    setOrders(prev => 
      prev.map(order => 
        order._id === updatedOrder._id ? updatedOrder : order
      )
    );
  };

  const handleOrderDelete = (orderId: string) => {
    setOrders(prev => prev.filter(order => order._id !== orderId));
  };

  const activeOrders = orders.filter(order => 
    ['PENDING', 'CONFIRMED', 'PREPARING', 'READY'].includes(order.status)
  );

  if (loading && orders.length === 0) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center">
        <div className="text-center">
          <LoadingSpinner size="lg" className="mb-4" />
          <p className="text-gray-600 text-lg">Loading kitchen dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {/* Header */}
      <header className="bg-white shadow-lg border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-6">
            <div className="flex items-center gap-4">
              <div className="text-3xl">👨‍🍳</div>
              <div>
                <h1 className="text-3xl font-bold text-gray-900">Kitchen Dashboard</h1>
                <p className="text-gray-600">Real-time order management system</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all duration-200 ${
                connected 
                  ? 'bg-green-100 text-green-800 border border-green-200' 
                  : 'bg-red-100 text-red-800 border border-red-200'
              }`}>
                <div className={`w-3 h-3 rounded-full ${
                  connected ? 'bg-green-600 animate-pulse' : 'bg-red-600'
                }`}></div>
                {connected ? 'Connected' : 'Disconnected'}
              </div>

              {newOrderCount > 0 && (
                <div className="bg-red-500 text-white px-3 py-1 rounded-full text-sm font-bold animate-bounce">
                  {newOrderCount} new
                </div>
              )}

              <button
                onClick={() => {
                  fetchOrders();
                  setNewOrderCount(0);
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all duration-200 flex items-center gap-2"
              >
                <span>🔄</span>
                Refresh
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Active Orders Summary */}
        {activeOrders.length > 0 && (
          <div className="mb-6 p-4 bg-gradient-to-r from-orange-50 to-red-50 border border-orange-200 rounded-xl">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-2xl">🔥</span>
                <div>
                  <div className="text-lg font-bold text-orange-800">
                    {activeOrders.length} Active Orders
                  </div>
                  <div className="text-sm text-orange-600">
                    Need attention now
                  </div>
                </div>
              </div>
              <div className="text-3xl animate-pulse">⚡</div>
            </div>
          </div>
        )}

        {/* Order Statistics */}
        <OrderStats orders={orders} />

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-6 flex items-center gap-3">
            <span className="text-2xl">❌</span>
            <div>
              <div className="text-red-800 font-medium">Connection Error</div>
              <div className="text-red-600 text-sm">{error}</div>
            </div>
          </div>
        )}

        {/* Orders List */}
        {orders.length === 0 && !loading ? (
          <div className="text-center py-16 bg-white rounded-xl shadow-lg">
            <div className="text-6xl mb-4">🍽️</div>
            <div className="text-2xl font-bold text-gray-400 mb-2">No orders yet</div>
            <div className="text-gray-500 mb-4">New orders will appear here in real-time</div>
            <button
              onClick={fetchOrders}
              className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all duration-200"
            >
              Check for Orders
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Sort orders by status and creation time */}
            {orders
              .sort((a, b) => {
                const statusPriority = {
                  'PENDING': 0,
                  'CONFIRMED': 1,
                  'PREPARING': 2,
                  'READY': 3,
                  'COMPLETED': 4,
                  'CANCELLED': 5
                };

                const aPriority = statusPriority[a.status] || 999;
                const bPriority = statusPriority[b.status] || 999;

                if (aPriority !== bPriority) {
                  return aPriority - bPriority;
                }

                return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
              })
              .map(order => (
                <OrderCard
                  key={order._id}
                  order={order}
                  onUpdate={handleOrderUpdate}
                  onDelete={handleOrderDelete}
                />
              ))}
          </div>
        )}
      </div>

      {/* Footer */}
      <footer className="bg-white border-t border-gray-200 mt-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex justify-between items-center">
            <div className="text-sm text-gray-600">
              Digital Menu SaaS - Kitchen Dashboard v1.0
            </div>
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <span>Powered by</span>
              <span className="text-2xl">⚡</span>
              <span>Real-time WebSocket</span>
            </div>
          </div>
        </div>
